const ACCESS_RANK = {
  none: 0,
  view: 1,
  edit: 2,
  admin: 3
};
function accessSatisfies(level, required) {
  return ACCESS_RANK[level] >= ACCESS_RANK[required];
}
function canEditAccess(level) {
  return accessSatisfies(level, "edit");
}
function canViewAccess(level) {
  return accessSatisfies(level, "view");
}
const NO_ACCESS = {
  level: "none",
  isOwner: false,
  exists: false
};
function parseAccess(data) {
  if (data && typeof data === "object" && !Array.isArray(data)) {
    const o = data;
    const level = o.level;
    if ((level === "view" || level === "edit" || level === "admin" || level === "none") && typeof o.is_owner === "boolean" && typeof o.exists === "boolean") {
      return {
        level,
        isOwner: o.is_owner,
        exists: o.exists
      };
    }
  }
  return null;
}
async function resolveResourceAccess(client, resourceType, resourceId, options = {}) {
  if (!resourceType || !resourceId) return NO_ACCESS;
  try {
    const { data, error } = await client.rpc("get_resource_access", {
      p_resource_type: resourceType,
      p_resource_id: resourceId
    });
    if (error) {
      if (options.strict) throw error;
      return NO_ACCESS;
    }
    const access = parseAccess(data);
    if (!access) {
      if (options.strict) {
        throw new Error("get_resource_access returned a malformed response");
      }
      return NO_ACCESS;
    }
    return access;
  } catch (error) {
    if (options.strict) throw error;
    return NO_ACCESS;
  }
}
export {
  NO_ACCESS,
  accessSatisfies,
  canEditAccess,
  canViewAccess,
  resolveResourceAccess
};
