import { supabase } from "../../../../host/db.js";
import { hasBrowserSession } from "../../../../host/identity.js";
async function waitForConversationPersisted(conversationId, {
  signal,
  timeoutMs = 18e4,
  intervalMs = 250,
  maxIntervalMs = 1500
} = {}) {
  if (!await hasBrowserSession()) {
    console.info(
      `[conversation-persistence] Guest session \u2014 skipping persistence poll for ${conversationId} (URL stays on /new; server persists under the guest's anonymous user).`
    );
    return false;
  }
  const deadline = Date.now() + timeoutMs;
  let delay = intervalMs;
  for (; ; ) {
    if (signal?.aborted) return false;
    const { data } = await supabase.schema("chat").from("conversation").select("id").eq("id", conversationId).is("deleted_at", null).maybeSingle();
    if (data) return true;
    if (Date.now() >= deadline) return false;
    await new Promise((resolve) => setTimeout(resolve, delay));
    delay = Math.min(Math.round(delay * 1.4), maxIntervalMs);
  }
}
export {
  waitForConversationPersisted
};
